action.command:
mkdir -p /run/qisutu && cat > /usr/local/bin/systemctl <<'SHIM_EOF'
#!/usr/bin/env bash
# Minimal systemctl shim for a container environment without a running systemd.
# Maps the service names used by Qisutu (apache2, mariadb, *-daemon.service,
# *-install-complete.path/.service) to direct process management.
# Every call is appended to /var/log/qisutu-systemctl-shim.log.
LOG=/var/log/qisutu-systemctl-shim.log
STATE=/run/qisutu/systemctl.state
mkdir -p /run/qisutu
echo "[$(date '+%F %T')] systemctl $*" >>"$LOG"

QUIET=0; NOW=0
args=()
for a in "$@"; do
    case "$a" in
        --quiet) QUIET=1 ;;
        --now) NOW=1 ;;
        -*) ;;
        *) args+=("$a") ;;
    esac
done
cmd="${args[0]:-}"
unit="${args[1]:-}"
[ -n "$unit" ] || unit="${args[0]:-}"
[ -n "$cmd" ] && [ "$cmd" = "$unit" ] && unit="${args[1]:-}"

# --- unit classification -------------------------------------------------
unit_kind() {
    case "$1" in
        apache2) echo svc-apache ;;
        mariadb|mysql) echo svc-mariadb ;;
        *.path)
            case "$1" in
                *-install-complete.path) echo path ;;
                *) echo other ;;
            esac ;;
        *.service)
            case "$1" in
                *-install-complete.service) echo oneshot ;;
                *-daemon.service) echo daemon ;;
                *) echo other ;;
            esac ;;
        *) echo other ;;
    esac
}

# --- state helpers -------------------------------------------------------
state_get() { grep -F " $1" "$STATE" 2>/dev/null | awk '{print $2}'; }
state_set() {
    local key="$1" val="$2"
    grep -v -F " $key" "$STATE" 2>/dev/null > "$STATE.tmp" || true
    echo "$key $val" >>"$STATE.tmp"
    mv "$STATE.tmp" "$STATE"
}

# --- service implementations ----------------------------------------------
mariadb_running() { mariadb-admin ping >/dev/null 2>&1; }

start_mariadb() {
    mariadb_running && return 0
    mkdir -p /run/mysqld && chown mysql:mysql /run/mysqld
    if [ ! -d /var/lib/mysql/mysql ]; then
        mariadb-install-db --user=mysql --datadir=/var/lib/mysql >>"$LOG" 2>&1 || return 1
    fi
    /usr/bin/mysqld --user=mysql --datadir=/var/lib/mysql >>"$LOG" 2>&1 &
    disown
    for _ in $(seq 1 60); do
        mariadb_running && return 0
        sleep 1
    done
    echo "shim: mariadb did not become ready" >&2
    return 1
}

stop_mariadb() {
    mariadb_running || return 0
    mariadb-admin shutdown >/dev/null 2>&1
    for _ in $(seq 1 30); do
        mariadb_running || return 0
        sleep 1
    done
    pkill -x mysqld
    sleep 2
    return 0
}

apache2_running() { pgrep -x apache2 >/dev/null 2>&1; }

start_apache() {
    if apache2_running; then
        /usr/sbin/apache2ctl graceful >/dev/null 2>&1 || true
        return 0
    fi
    /usr/sbin/apachectl start >>"$LOG" 2>&1 || /usr/sbin/service apache2 start >>"$LOG" 2>&1
    apache2_running
}

stop_apache() {
    apache2_running || return 0
    /usr/sbin/apachectl stop >>"$LOG" 2>&1 || /usr/sbin/service apache2 stop >>"$LOG" 2>&1
    return 0
}

unit_file() {
    case "$1" in
        *.service|*.path) echo "/etc/systemd/system/$1" ;;
        *) echo "/etc/systemd/system/$1.service" ;;
    esac
}

daemon_base() { echo "${1%.service}"; }

daemon_running() {
    local base pidfile pid
    base="$(daemon_base "$1")"
    pidfile="/run/qisutu/$base.pid"
    [ -f "$pidfile" ] || return 1
    pid="$(cat "$pidfile" 2>/dev/null)"
    [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null
}

start_daemon() {
    local f base pidfile user group
    f="$(unit_file "$1")"
    base="$(daemon_base "$1")"
    pidfile="/run/qisutu/$base.pid"
    daemon_running "$1" && return 0
    user="$(sed -n 's/^User=//p' "$f")"
    group="$(sed -n 's/^Group=//p' "$f")"
    [ -n "$user" ] || user="qisutu"
    setsid runuser -u "$user" -g "$group" -- "$(sed -n 's/^ExecStart=//p' "$f")" >>"$LOG" 2>&1 &
    echo $! >"$pidfile"
    sleep 1
    daemon_running "$1"
}

stop_daemon() {
    local f base pidfile pid
    f="$(unit_file "$1")"
    base="$(daemon_base "$1")"
    pidfile="/run/qisutu/$base.pid"
    if [ -f "$pidfile" ]; then
        pid="$(cat "$pidfile" 2>/dev/null)"
        if [ -n "$pid" ]; then
            kill "$pid" 2>/dev/null || true
            for _ in $(seq 1 15); do
                kill -0 "$pid" 2>/dev/null || break
                sleep 1
            done
            kill -0 "$pid" 2>/dev/null && kill -9 "$pid" 2>/dev/null || true
        fi
        rm -f "$pidfile"
    fi
    # also catch stray instances of this specific daemon path
    local execstart
    execstart="$(sed -n 's/^ExecStart=//p' "$f" 2>/dev/null | sed 's/^.*qisutu-daemon\.pl/qisutu-daemon.pl/')"
    pkill -f "qisutu-daemon.pl.*" 2>/dev/null | grep -q . && sleep 1 || true
    return 0
}

path_active() { grep -qF " path-$1=active" "$STATE" 2>/dev/null; }
path_activate() { state_set "path-$1" active; }
path_deactivate() { state_set "path-$1" inactive; }

oneshot_run() {
    # *-install-complete.service: enable daemon, remove temp units
    local f="$1" svc base
    svc="$(sed -n 's/.*systemctl enable --now \([^ ]*\).*/\1/p' "$f")"
    f="$(unit_file "$svc")"
    base="$(daemon_base "$svc")"
    state_set "daemon-$base" enabled
    start_daemon "$svc" || return 1
    path_deactivate "${base}-install-complete.path"
    rm -f "/etc/systemd/system/${base}-install-complete.path" "/etc/systemd/system/${base}-install-complete.service"
    return 0
}

is_active() {
    local kind
    kind="$(unit_kind "$1")"
    case "$kind" in
        svc-apache) apache2_running ;;
        svc-mariadb) mariadb_running ;;
        daemon) daemon_running "$1" ;;
        path) path_active "$1" ;;
        *) return 3 ;;
    esac
}

do_start() {
    local kind
    kind="$(unit_kind "$1")"
    case "$kind" in
        svc-apache) start_apache ;;
        svc-mariadb) start_mariadb ;;
        daemon) start_daemon "$1" ;;
        path) path_activate "$1"; return 0 ;;
        oneshot) oneshot_run "$1" ;;
        *) echo "shim: unsupported start $1" >&2; return 0 ;;
    esac
}

do_stop() {
    local kind
    kind="$(unit_kind "$1")"
    case "$kind" in
        svc-apache) stop_apache ;;
        svc-mariadb) stop_mariadb ;;
        daemon) stop_daemon "$1" ;;
        path) path_deactivate "$1"; return 0 ;;
        oneshot) return 0 ;;
        *) return 0 ;;
    esac
}

case "$cmd" in
    start) do_start "$unit" ;;
    stop) do_stop "$unit" ;;
    restart) do_stop "$unit"; do_start "$unit" ;;
    enable) state_set "unit-${unit//\//_}" enabled; [ "$NOW" = 1 ] && do_start "$unit" ;;
    disable) state_set "unit-${unit//\//_}" disabled; [ "$NOW" = 1 ] && do_stop "$unit" ;;
    is-active) is_active "$unit" ;;
    is-enabled) [ "$(state_get "unit-${unit//\//_}")" = "enabled" ];;
    daemon-reload) : ;;
    reload|reload-or-restart) do_stop "$unit"; do_start "$unit" ;;
    status) is_active "$unit" && { [ "$QUIET" = 1 ] || echo "shim: $unit active"; } ;;
    *) [ "$QUIET" = 1 ] || echo "shim: unhandled command: $cmd $unit" >&2; exit 0 ;;
esac
SHIM_EOF
chmod 755 /usr/local/bin/systemctl && bash -n /usr/local/bin/systemctl && echo "SYNTAX OK" && which systemctl

